        <div v-if="errorMessage" class="admin-owner-state error"><strong>{{ $t('legacy.t_7f7fe4852d9d') }}</strong><span>{{ errorMessage }}</span><button @click="loadData">{{ $t('legacy.t_0c9157b5bfac') }}</button></div>
