                <td class="money-green">{{ $t('legacy.t_5e7b60c626a4') }} {{ money(row.amountPaid) }}</td><td><b class="money-red">{{ $t('legacy.t_5e7b60c626a4') }} {{ money(row.outstandingAmount) }}</b></td>
                <td>{{ row.dueDate }}<small v-if="row.overdueDays">{{ $t('legacy.t_65a02a484e43') }} {{ row.overdueDays }} {{ $t('legacy.t_c3304d1e49e3') }}</small></td>
