          <div class="detail-actions finance-review-actions"><button class="confirm" @click="openConfirm">{{ $t('legacy.t_b52efc165fe3') }}</button><button @click="goToTenancy">{{ $t('legacy.t_bcdce2d6efbe') }}</button><button v-if="selectedRow.latestProofDocumentId" @click="openProof">{{ $t('legacy.t_df40a55c9e1c') }}</button></div>
          <div class="detail-section"><h4><span class="num">{{ $t('legacy.t_356a192b7913') }}</span>{{ $t('legacy.t_edeb2ce5b99b') }}</h4><div class="kv"><span>{{ $t('legacy.t_bd95f007d6d0') }}</span><b>{{ selectedRow.leaseNo }}</b></div><div class="kv"><span>{{ $t('legacy.t_a7ff541f4978') }}</span><b>{{ monthLabel(selectedRow.billingMonth) }}</b></div><div class="kv"><span>{{ $t('legacy.t_fdeda5befee2') }}</span><b>{{ $t('legacy.t_5e7b60c626a4') }} {{ money(selectedRow.amountDue) }}</b></div><div class="kv"><span>{{ $t('legacy.t_eece4b5b3b99') }}</span><b class="money-green">{{ $t('legacy.t_5e7b60c626a4') }} {{ money(selectedRow.amountPaid) }}</b></div><div class="kv"><span>{{ $t('legacy.t_3060acf4dcc3') }}</span><b class="money-red">{{ $t('legacy.t_5e7b60c626a4') }} {{ money(selectedRow.outstandingAmount) }}</b></div><div class="progress"><i :style="{width:paymentProgress+'%'}"></i></div></div>
          <div class="detail-section"><h4><span class="num">{{ $t('legacy.t_da4b9237bacc') }}</span>{{ $t('legacy.t_871046484e52') }}</h4><div class="kv"><span>{{ $t('legacy.t_11cb5e87977f') }}</span><b>{{ selectedRow.dueDate }}</b></div><div class="kv"><span>{{ $t('legacy.t_608d8eca243f') }}</span><b>{{ selectedRow.overdueDays ? `${selectedRow.overdueDays} 天` : $t('legacy.t_9f484e581ae0') }}</b></div><div class="kv"><span>{{ $t('legacy.t_27b064666adf') }}</span><b>{{ $t('legacy.t_5e7b60c626a4') }} {{ money(selectedRow.outstandingAmount) }}</b></div></div>
          <div class="detail-section"><h4><span class="num">{{ $t('legacy.t_77de68daecd8') }}</span>{{ $t('legacy.t_969d16f00bbf') }}</h4><div v-if="selectedRow.latestFinanceRecordId"><div class="kv"><span>{{ $t('legacy.t_32e88cf956f6') }}</span><b>{{ selectedRow.latestTransactionNo }}</b></div><div class="kv"><span>{{ $t('legacy.t_b35a920fa6f3') }}</span><b>{{ $t('legacy.t_5e7b60c626a4') }} {{ money(selectedRow.latestPaymentAmount) }}</b></div><div class="kv"><span>{{ $t('legacy.t_9afa4ce0531c') }}</span><b>{{ selectedRow.latestPaymentDate }}</b></div><div class="kv"><span>{{ $t('legacy.t_c6b9a8cfdb21') }}</span><b>{{ paymentMethodLabel(selectedRow.latestPaymentMethod) }}</b></div><div class="kv"><span>{{ $t('legacy.t_41ee43593eb7') }}</span><b>{{ selectedRow.latestProofName || $t('legacy.t_4ca99b833c98') }}</b></div></div><p v-else class="empty-note">{{ $t('legacy.t_114205cf08dd') }}</p></div>
        </template>
        <div v-else class="admin-owner-empty">{{ $t('legacy.t_c1805f1ba82d') }}</div>
      </aside>

      <dialog ref="confirmDialog" class="rent-confirm-dialog">
        <form @submit.prevent="submitConfirm">
          <header><div><h3>{{ $t('legacy.t_19c50942ffc4') }}</h3><p>{{ selectedRow?.tenantName }} · {{ selectedRow?.leaseNo }}</p></div><button type="button" @click="closeConfirm">×</button></header>
          <p v-if="actionError" ref="confirmError" class="rent-action-error" role="alert">{{ actionError }}</p>
          <div class="rent-confirm-body">
            <div class="rent-amount-summary"><span>{{ $t('legacy.t_fdeda5befee2') }}<b>{{ $t('legacy.t_5e7b60c626a4') }} {{ money(selectedRow?.amountDue) }}</b></span><span>{{ $t('legacy.t_eece4b5b3b99') }}<b>{{ $t('legacy.t_5e7b60c626a4') }} {{ money(selectedRow?.amountPaid) }}</b></span><span>{{ $t('legacy.t_3060acf4dcc3') }}<b class="money-red">{{ $t('legacy.t_5e7b60c626a4') }} {{ money(selectedRow?.outstandingAmount) }}</b></span></div>
            <div class="rent-form-grid"><label>{{ $t('legacy.t_67aa62936fbc') }}<input v-model="form.amount" type="number" min="0.01" step="0.01" required><small v-if="advanceRentSummary" class="advance-rent-hint">{{ advanceRentSummary }}</small></label><label>{{ $t('legacy.t_9afa4ce0531c') }}<input v-model="form.paymentDate" type="date" :max="todayDate" required></label></div>
            <div class="rent-form-grid"><label>{{ $t('legacy.t_c6b9a8cfdb21') }}<select v-model="form.paymentMethod" required><option value="bank_transfer">{{ $t('legacy.t_789957b63e04') }}</option><option value="online_payment">{{ $t('legacy.t_6e249e45b116') }}</option><option value="cash">{{ $t('legacy.t_e3ca5905c270') }}</option><option value="cheque">{{ $t('legacy.t_61b73b219228') }}</option><option value="security_deposit">{{ $t('tenancy.securityDepositPayment') }}</option></select></label><label>{{ $t('legacy.t_d61f1eba334a') }}<input v-model.trim="form.payerName" maxlength="160" required></label></div>
            <label>{{ $t('legacy.t_91cdcd88db53') }}<input v-model.trim="form.paymentReference" maxlength="120" :disabled="form.paymentMethod==='security_deposit'" :placeholder="['cash','security_deposit'].includes(form.paymentMethod)?$t('legacy.t_9b64abbc22ab'):$t('legacy.t_1d9252b6daad')"></label>
            <label>{{ $t('legacy.t_f8aa34f40d01') }}<input ref="proofInput" type="file" accept="application/pdf,image/jpeg,image/png" @change="selectProof"><small>{{ proof?.name || $t('legacy.t_b35320f63845') }}</small></label>
            <label>{{ $t('legacy.t_0c819d5d6459') }}<textarea v-model.trim="form.note" maxlength="500" rows="3"></textarea></label>
            <div class="rent-confirm-notice"><b>{{ afterStatusText }}</b><span>{{ $t('legacy.t_5b9ebee75501') }}</span></div>
          </div>
          <menu><button type="button" @click="closeConfirm">{{ $t('legacy.t_4d0b4688c787') }}</button><button class="primary-btn" type="submit" :disabled="saving">{{ saving?$t('legacy.t_6a9b39fafbcc'):$t('legacy.t_6b8683619d6e') }}</button></menu>
        </form>
      </dialog>

      <dialog ref="proofDialog" class="modal admin-finance-proof-dialog"><div class="modal-head"><div><h3>{{ $t('legacy.t_bf3848894d3f') }}</h3><small>{{ selectedRow?.latestProofName }}</small></div><button class="icon-close" @click="closeProof">×</button></div><div class="finance-proof-viewer"><div v-if="proofLoading" class="admin-owner-state">{{ $t('legacy.t_6ce3778a43cd') }}</div><img v-else-if="proofUrl&&selectedRow?.latestProofMimeType?.startsWith('image/')" :src="proofUrl"><iframe v-else-if="proofUrl&&selectedRow?.latestProofMimeType==='application/pdf'" :src="proofUrl"></iframe><div v-else class="admin-owner-state">{{ proofError||$t('legacy.t_7db08b273aa4') }}</div></div><menu><button @click="closeProof">{{ $t('legacy.t_ddc05404b0d6') }}</button></menu></dialog>
    </section>
  </div>
</template>

<script>
import { confirmAdminRentCollection, fetchAdminRentCollectionProjects, fetchAdminRentCollections, fetchAdminRentProof, fetchAdminRentReceipt } from '../services/propertyApi';
const localToday=()=>{const d=new Date();d.setMinutes(d.getMinutes()-d.getTimezoneOffset());return d.toISOString().slice(0,10);};
export default {
  inject:['page'],
  data(){return{rows:[],selectedId:null,pageNumber:1,pageSize:5,totalRows:0,totalPages:1,loading:false,errorMessage:'',requestSerial:0,todayDate:localToday(),form:{amount:'',paymentDate:localToday(),paymentMethod:'bank_transfer',payerName:'',paymentReference:'',note:''},proof:null,saving:false,actionError:'',proofLoading:false,proofUrl:'',proofError:''};},
  computed:{selectedRow(){return this.rows.find(r=>r.invoiceId===this.selectedId)||this.rows[0]||null;},visiblePages(){const start=Math.max(1,Math.min(this.pageNumber-2,this.totalPages-4));return Array.from({length:Math.min(5,this.totalPages)},(_,i)=>start+i);},paymentProgress(){return !Number(this.selectedRow?.amountDue)?0:Math.min(100,Math.round(Number(this.selectedRow.amountPaid||0)/Number(this.selectedRow.amountDue)*100));},collectionNonce(){return this.page.adminRentCollectionNonce;},advanceRentPlan(){const row=this.selectedRow,amount=Number(this.form.amount||0);if(!row||!Number.isFinite(amount)||amount<=0)return null;let remaining=amount,month=this.monthStart(row.billingMonth),lastMonth=this.monthStart(row.leaseEndDate),months=0,last=null;while(remaining>0.005&&month&&lastMonth&&month<=lastMonth){const due=month===this.monthStart(row.billingMonth)?Number(row.outstandingAmount||0):this.monthlyInvoiceAmount(row,month);if(due>0){const paid=Math.min(remaining,due);months+=1;last={paid,due,remaining:Math.max(due-paid,0)};remaining-=paid;}month=this.addMonth(month);}return{months,last,exceeds:remaining>0.005};},advanceRentSummary(){const plan=this.advanceRentPlan;if(!plan)return '';if(plan.exceeds)return this.$t('tenancy.advanceRentExceedsLease');let text=this.$t('tenancy.advanceRentMonths',{months:plan.months});if(plan.last?.remaining>0.005)text+=` ${this.$t('tenancy.advanceRentPartial',{amount:this.money(plan.last.paid),due:this.money(plan.last.due),remaining:this.money(plan.last.remaining)})}`;return text;},afterStatusText(){const remaining=Number(this.selectedRow?.outstandingAmount||0)-Number(this.form.amount||0);if(this.advanceRentPlan?.exceeds)return this.$t('tenancy.advanceRentExceedsLease');return remaining<=0?'本期租金將標記為已收齊':`入帳後仍有 RM ${this.money(Math.max(remaining,0))} 待收`; }},
  watch:{'page.moduleSearch'(){this.resetLoad();},'page.globalSearch'(){this.resetLoad();},'page.projectFilter'(){this.resetLoad();},'page.statusFilter'(){this.resetLoad();},'page.dateStart'(){this.resetLoad();},'page.dateEnd'(){this.resetLoad();},pageSize(){this.pageNumber=1;this.loadData();},collectionNonce(v,p){if(v>p)this.$nextTick(this.openConfirm);},rows:{deep:true,handler(v){if(!v.some(r=>r.invoiceId===this.selectedId))this.selectedId=v[0]?.invoiceId||null;}}},
  mounted(){this.loadData();},beforeUnmount(){this.revokeProof();},
  methods:{
    async loadData(){const serial=++this.requestSerial,preferred=this.selectedId;this.loading=true;this.errorMessage='';try{const [response,projects]=await Promise.all([fetchAdminRentCollections({page:this.pageNumber,pageSize:this.pageSize,keyword:this.page.globalSearch||this.page.moduleSearch||'',projectName:String(this.page.projectFilter||'').includes('全部')?'':this.page.projectFilter,status:this.statusParam(this.page.statusFilter),startDate:this.page.dateStart,endDate:this.page.dateEnd}),fetchAdminRentCollectionProjects()]);if(serial!==this.requestSerial)return;this.rows=response.rows||[];this.totalRows=response.page?.totalRows||0;this.totalPages=response.page?.totalPages||1;this.pageNumber=response.page?.page||1;this.selectedId=this.rows.some(r=>r.invoiceId===preferred)?preferred:this.rows[0]?.invoiceId||null;this.page.adminFinanceProjects=projects||[];this.page.adminFinanceMetrics=this.metrics(response.summary||{});}catch(e){if(serial!==this.requestSerial)return;this.rows=[];this.errorMessage=e.message||'API request failed';this.page.adminFinanceMetrics=null;}finally{if(serial===this.requestSerial)this.loading=false;}},
    metrics(s){return[{label:'待收租金帳單',value:`${Number(s.outstandingCount||0)} 筆`,delta:`RM ${this.money(s.outstandingAmount)}`,trend:Number(s.outstandingCount)?'down':'up'},{label:'完全未支付',value:`${Number(s.unpaidCount||0)} 筆`,delta:'尚未收到任何款項',trend:Number(s.unpaidCount)?'down':'up'},{label:'部分支付',value:`${Number(s.partialCount||0)} 筆`,delta:'仍需繼續收款',trend:Number(s.partialCount)?'down':'up'},{label:'逾期帳單',value:`${Number(s.overdueCount||0)} 筆`,delta:'需要跟進',trend:Number(s.overdueCount)?'down':'up'},{label:'本月已收租金',value:`RM ${this.money(s.monthReceived)}`,delta:'已確認入帳',trend:'up'}];},
    resetLoad(){this.pageNumber=1;this.loadData();},goPage(n){if(n>=1&&n<=this.totalPages&&n!==this.pageNumber){this.pageNumber=n;this.loadData();}},selectAndConfirm(row){this.selectedId=row.invoiceId;this.$nextTick(this.openConfirm);},
    openConfirm(){if(!this.selectedRow)return;this.form={amount:Number(this.selectedRow.outstandingAmount||0).toFixed(2),paymentDate:localToday(),paymentMethod:'bank_transfer',payerName:this.selectedRow.tenantName||'',paymentReference:'',note:''};this.proof=null;this.actionError='';if(this.$refs.proofInput)this.$refs.proofInput.value='';this.$refs.confirmDialog?.showModal();},closeConfirm(){if(!this.saving)this.$refs.confirmDialog?.close();},showConfirmError(message){this.actionError=message;},selectProof(e){const f=e.target.files?.[0]||null;if(f&&(!['application/pdf','image/jpeg','image/png'].includes(f.type)||f.size>10*1024*1024)){this.showConfirmError('只支援 10MB 以內的 PDF、JPG 或 PNG 憑證');e.target.value='';this.proof=null;return;}this.proof=f;},
    async submitConfirm(){const amount=Number(this.form.amount);if(!Number.isFinite(amount)||amount<=0){this.showConfirmError('本次實收金額必須大於 0。');return;}if(this.form.paymentMethod==='security_deposit'&&amount>Number(this.selectedRow?.outstandingAmount||0)){this.showConfirmError(this.$t('tenancy.securityDepositCurrentOnly'));return;}if(this.advanceRentPlan?.exceeds){this.showConfirmError(this.$t('tenancy.advanceRentExceedsLease'));return;}if(!['cash','security_deposit'].includes(this.form.paymentMethod)&&!this.form.paymentReference){this.showConfirmError('非現金收款必須填寫銀行或付款參考。');return;}this.saving=true;this.actionError='';try{const result=await confirmAdminRentCollection(this.selectedRow.invoiceId,{...this.form,paymentReference:this.form.paymentMethod==='security_deposit'?null:this.form.paymentReference,amount:amount.toFixed(2)},this.proof);this.$refs.confirmDialog?.close();await this.loadData();this.page.showToast(`租金已確認入帳：${result.referenceNo}，收據已產生`);if(result.id) await this.downloadReceipt(result.id,result.receiptNo);}catch(e){this.showConfirmError(e.message||'租金確認失敗');}finally{this.saving=false;}},
    async openProof(){if(!this.selectedRow?.latestProofDocumentId)return;this.revokeProof();this.proofLoading=true;this.proofError='';this.$refs.proofDialog?.showModal();try{const r=await fetchAdminRentProof(this.selectedRow.latestProofDocumentId);this.proofUrl=URL.createObjectURL(r.blob);}catch(e){this.proofError=e.message||'憑證載入失敗';}finally{this.proofLoading=false;}},closeProof(){this.$refs.proofDialog?.close();this.revokeProof();},revokeProof(){if(this.proofUrl)URL.revokeObjectURL(this.proofUrl);this.proofUrl='';},async downloadReceipt(id,receiptNo){try{const r=await fetchAdminRentReceipt(id);this.saveBlob(r.blob,`rent-receipt-${receiptNo||id}.pdf`);this.page.showToast('租金收據下載已開始');}catch(e){this.page.showToast(e.message||'租金收據下載失敗');}},saveBlob(blob,fileName){const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download=fileName;link.style.display='none';document.body.appendChild(link);link.click();window.setTimeout(()=>{link.remove();URL.revokeObjectURL(url);},1000);},goToTenancy(){const k=this.selectedRow?.tenantName||'';this.page.selectModule('adminTenants');this.$nextTick(()=>{this.page.globalSearch=k;});},monthStart(v){return v?String(v).slice(0,10):'';},addMonth(v){const [year,month]=v.split('-').map(Number);return `${month===12?year+1:year}-${String(month===12?1:month+1).padStart(2,'0')}-01`;},monthlyInvoiceAmount(row,month){const monthlyRent=Number(row.monthlyRent||0);if(row.rentCalculationMethod!=='daily_prorated')return monthlyRent;const start=Math.max(new Date(`${row.leaseStartDate}T00:00:00Z`).getTime(),new Date(`${month}T00:00:00Z`).getTime());const monthEnd=new Date(`${month.slice(0,7)}-01T00:00:00Z`);monthEnd.setUTCMonth(monthEnd.getUTCMonth()+1);const end=Math.min(new Date(`${row.leaseEndDate}T00:00:00Z`).getTime(),monthEnd.getTime()-86400000);if(start>end)return 0;const days=Math.round((end-start)/86400000)+1;const daysInMonth=new Date(Date.UTC(Number(month.slice(0,4)),Number(month.slice(5,7)),0)).getUTCDate();return Math.max(Number((monthlyRent*days/daysInMonth).toFixed(2)),monthlyRent>0?0.01:0);},statusParam(v){return({'未支付':'unpaid','部分支付':'partial','已逾期':'overdue'})[v]||'';},statusLabel(v){return({unpaid:'未支付',partial:'部分支付',overdue:'已逾期'})[v]||v;},statusClass(v){return v==='partial'?'orange':v==='overdue'?'red':'gray';},paymentMethodLabel(v){return({bank_transfer:'銀行轉帳',online_payment:'線上支付',cash:'現金',cheque:'支票',security_deposit:this.$t('tenancy.securityDepositPayment')})[v]||v||'—';},monthLabel(v){return v?String(v).slice(0,7):'—';},money(v){return Number(v||0).toLocaleString('en-MY',{minimumFractionDigits:2,maximumFractionDigits:2});}
  }
};
</script>

